update aurea_crm_records as r
set data = r.data || jsonb_build_object(
  'email', case when coalesce(r.data->>'email','')='' then v.email else r.data->>'email' end,
  'phone', case when coalesce(r.data->>'phone','')='' then v.phone else r.data->>'phone' end,
  'contactSource',v.url,
  'contactVerifiedAt','2026-11-22'
), updated_at=now()
from verified as v
where r.kind=v.kind and lower(r.data->>'name')=lower(v.company);

